svg.script:
function cover(id, offset) {
  let element = document.getElementById(id);
  element.dy.baseVal[0].value = offset;
  let rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");
  let bbox = element.getBBox();
  // Inflate by a couple pixels, to prevent antialiasing failures.
  rect.x.baseVal.value = bbox.x - 2;
  rect.y.baseVal.value = bbox.y - 2;
  rect.width.baseVal.value = bbox.width + 4;
  rect.height.baseVal.value = bbox.height + 4;
  element.parentElement.appendChild(rect);
}
onload = function() {
  document.fonts.ready.then(() => {
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    ctx.font = '25px test';

    // GetBaselinePosition() in layout/svg/SVGTextFrame.cpp puts the hanging
    // and the mathematical baselines at 0.2 and 0.5 of the text run's ascent
    // below the text-before-edge baseline, which is the one the covering
    // text uses.
    let ascent = ctx.measureText('h').fontBoundingBoxAscent;

    cover("hanging", -0.2 * ascent);

    cover("mathematical", -0.5 * ascent);

    document.documentElement.removeAttribute('class');
  });
}
